package in.industrend.social;import java.util.Map;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;@RestControllerAdvice class ApiExceptionHandler{@ExceptionHandler(IllegalArgumentException.class)ResponseEntity<?>bad(IllegalArgumentException e){return ResponseEntity.badRequest().body(Map.of("error",e.getMessage()));}@ExceptionHandler(Exception.class)ResponseEntity<?>server(Exception e){return ResponseEntity.status(500).body(Map.of("error",e.getMessage()==null?"The request could not be completed":e.getMessage()));}}
